INSERT INTO membrane_retrofits(assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES
('A101-R1','R101-01','CN0374','historical_shared_station','restart_only',1,'仅在资产接续或复产时评估回用优化','停产清算背景下不推荐主动设备改造；如新业主复产，先核既有深度处理及分股盐/有机物，再比较膜回用','not_recommended','已停产，拟清算，未见复产或改造项目','S101-04/S101-05','INFERRED，非技术不可行','资产处置、复产、实际分股及处理费用','先核复产和接续责任，再现场采样及衡算','维持停产期间依法管理',NULL,NULL,NULL,NULL,NULL,NULL,'缺工程输入，不强评难度','2026-11-28');
INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N101-01','CN0371','S099-01','历史实际处理及运行经济','2.7.2表2.7-1，报告p102–103','2023执行报告经2024环评引用：运行8000h、处理及排放各6204.8t、回用栏/（非零）、电12000kWh、药1000kg、处理效率75%（因子未明）、运行费24万元。由同表计算38.68元/t、1.934kWh/t、0.161kg/t。无明细，不认全成本、不归900t/a新线。原PDF截图502、文本可读。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N101-02','CN0371','S099-01','历史监测及排放质量','2.3-1及2.7-4','13项历史总排口监测，保留丙烯腈0.6L及日期；年度14项全厂间接排放质量。一般口苯胺0.000619、动植物油0.000389t与全厂0.000618、0.000388微差；不相加。报告年度质量与离散监测浓度不可反推流量。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N101-03','CN0371','S099-01','历史催化剂装置及许可','表2.2-3、2.7.1','PEO专用催化剂2t/a，2016-10，表列实际能力2；FCC低磁剂3000t/a项目2010-10、表列已关停0。许可91220203723133114P001V，2023-05-11至2028-05-10为报告历史延续期限，现行变更待查。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N101-04','CN0373','S101-01','备案及厂址','备案正文','2022-03-14确认，项目代码2203-150303-04-01-405401，245亩、计划总投资5亿元，含THF三万吨与离子液催化剂1000吨，不把计划当实际。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N101-05','CN0373','S101-03','实际项目阶段边界','问题二','2023-03动工，2024-09 THF试生产及非生产性配套转固3874.64万元；2025-10生产资产转固21968.29万元主要THF装置配套，安全许可证取得；不作为催化剂专线环保验收。媒体S101-02称混合项目建成投产。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N101-06','CN0373','S101-07','新扩建事件','二次公示2026-11-21','扩建THF 1.2万吨、正丁醇6000吨；非催化剂产能，报告网盘链接未取正文，后续核共享污水站。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N101-07','CN0374','S101-04','历史处理能力及固废','第五节（五）p93–96','2020–22历史共享300m³/d能力，二级A/O和中水深度回用不外排。污水站废树脂2020/21/22实际1.92/1.52/2.04t，废活性炭2021实际0.20t、其他两年原表横线不判零；THF生产污泥0.48/0.14/0.32t，不算污水站污泥。2022树脂计划2t与实际2.04t，公司称已审核转移。2022催化材料项目正式投产，工艺膜分离属产品制备，不算污水膜。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N101-08','CN0374','S101-05','停产清算及地址','公告2026-08-28第二、三节','2025-01停产；董事会审议通过拟解散清算，未核注销或资产转让。地址兴庆区苏银产业园厚土东路1号。2025-05曾披露催化剂300t/a升级计划（S101-08），后续清算，不推定技改完成。','WEB_COMPANY','WEB_TEXT','2026-11-28');
